<?php require_once '../../includes/functions.php'; requireLogin(); global $pdo; $month = $_GET['month'] ?? date('Y-m'); $sql = "SELECT p.*, e.first_name, e.last_name, e.position, d.name as department_name FROM erp_payroll p JOIN erp_employees e ON p.employee_id = e.id LEFT JOIN erp_departments d ON e.department_id = d.id WHERE DATE_FORMAT(p.payroll_month, '%Y-%m') = ? ORDER BY e.first_name ASC"; $stmt = $pdo->prepare($sql); $stmt->execute([$month]); $payroll = $stmt->fetchAll(); $totalBasic = 0; $totalAllowances = 0; $totalDeductions = 0; $totalNet = 0; foreach ($payroll as $p) { $totalBasic += $p['basic_salary']; $totalAllowances += $p['allowances']; $totalDeductions += $p['deductions']; $totalNet += $p['net_salary']; } ?>
