    <div class="header"><h1>ðŸ’° Payroll</h1><div class="header-actions"><a href="../index.php" class="btn btn-secondary">â† Back</a><a href="run-payroll.php" class="btn btn-primary">Run Payroll</a></div></div>
    <div class="container"><div class="summary-cards"><div class="summary-card"><div class="summary-label">Total Basic Salary</div><div class="summary-value">TSh <?= number_format($totalBasic, 2) ?></div></div><div class="summary-card"><div class="summary-label">Total Allowances</div><div class="summary-value" style="color: #137333;">+ TSh <?= number_format($totalAllowances, 2) ?></div></div><div class="summary-card"><div class="summary-label">Total Deductions</div><div class="summary-value" style="color: #c5221f;">- TSh <?= number_format($totalDeductions, 2) ?></div></div><div class="summary-card"><div class="summary-label">Net Payable</div><div class="summary-value" style="color: #1a73e8;">TSh <?= number_format($totalNet, 2) ?></div></div></div>
    <div class="card"><div class="card-header"><form method="GET" class="filters"><label style="font-weight: 500; margin-right: 8px;">Month:</label><input type="month" name="month" value="<?= $month ?>" class="month-picker" onchange="this.form.submit()"></form><?php if (!empty($payroll)): ?><button onclick="window.print()" class="btn btn-secondary">Print Report</button><?php endif; ?></div>
    <table class="table"><thead><tr><th>Employee</th><th>Department</th><th>Basic Salary</th><th>Allowances</th><th>Deductions</th><th>Net Salary</th><th>Status</th><th>Actions</th></tr></thead><tbody>
    <?php if (empty($payroll)): ?><tr><td colspan="8" style="text-align: center; padding: 48px; color: #5f6368;">No payroll records found for this month.<br><br><a href="run-payroll.php" class="btn btn-primary">Run Payroll for <?= date('F Y', strtotime($month)) ?></a></td></tr><?php else: ?><?php foreach ($payroll as $p): ?><tr><td><div style="font-weight: 500;"><?= htmlspecialchars($p['first_name'] . ' ' . $p['last_name']) ?></div><div style="font-size: 0.75rem; color: #5f6368;"><?= htmlspecialchars($p['position']) ?></div></td><td><?= htmlspecialchars($p['department_name'] ?? '-') ?></td><td><?= number_format($p['basic_salary'], 2) ?></td><td style="color: #137333;"><?= number_format($p['allowances'], 2) ?></td><td style="color: #c5221f;"><?= number_format($p['deductions'], 2) ?></td><td style="font-weight: 600;"><?= number_format($p['net_salary'], 2) ?></td><td><?php $statusClass = ['draft' => 'badge-warning', 'approved' => 'badge-success', 'paid' => 'badge-success']; ?><span class="badge <?= $statusClass[$p['status']] ?? 'badge-info' ?>"><?= ucfirst($p['status']) ?></span></td><td><a href="view-payslip.php?id=<?= $p['id'] ?>" class="btn btn-secondary" style="padding: 4px 12px; font-size: 0.75rem;">Payslip</a></td></tr><?php endforeach; ?><?php endif; ?>
